def recipe_snapshot(extra_paths: list[Path] | None = None) -> tuple[list[dict], list[dict]]:
    """Return the embedded 87 recipes, then explicit later lists in supplied order."""
    documents = list(EMBEDDED_SOURCE_DOCUMENTS)
    for path in extra_paths or []:
        path = Path(path).expanduser()
        if path.suffix.lower() != '.json' or path.is_symlink():
            raise ValueError('Extra recipes must be explicit, nonsymlink .json files.')
        resolved = path.resolve(strict=True)
        if resolved.suffix.lower() != '.json' or not resolved.is_file():
            raise ValueError('Extra recipes must resolve to regular .json files.')
        raw = resolved.read_bytes()
        documents.append({'path': str(path), 'bytes': len(raw),
                          'sha256': hashlib.sha256(raw).hexdigest(),
                          'raw_json': raw.decode('utf-8')})
    recipes = []
    ids, filenames = set(), set()
    for index, document in enumerate(documents):
        raw = document['raw_json'].encode('utf-8')
        if len(raw) != document['bytes'] or hashlib.sha256(raw).hexdigest() != document['sha256']:
            raise ValueError('Recipe JSON differs from its captured provenance.')
        values = json.loads(document['raw_json'])
        if not isinstance(values, list):
            raise ValueError('Recipe JSON must contain a list.')
        if index < len(EMBEDDED_RECIPE_COUNTS) and len(values) != EMBEDDED_RECIPE_COUNTS[index]:
            raise ValueError('An embedded page-081 recipe set has an unexpected count.')
        for crop in values:
            validate_crop_metadata(crop)
            normalized = re.sub(r'[^A-Za-z0-9_.+-]+', '_', crop['id'])
            if crop['id'] in ids:
                raise ValueError('Duplicate crop ID across the base and extra recipe sets.')
            if normalized in filenames:
                raise ValueError('Normalized crop filenames collide across recipe sets.')
            if '..' in Path(crop['source']).parts:
                raise ValueError('Parent traversal is prohibited in crop sources.')
            ids.add(crop['id']); filenames.add(normalized)
            recipes.append(crop)
    return recipes, documents


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument('--metadata-only', action='store_true', help='Validate recipe metadata only; this is the default.')
    mode.add_argument('--render', action='store_true', help='Explicitly read the attached source images and render all selected recipes.')
    parser.add_argument('--extra-recipes', type=Path, action='append', default=[], metavar='FILE.json',
                        help='Append additional later recipes; repeat in order. The captured 19 fine recipes are already embedded.')
    parser.add_argument('--scan-root', type=Path, default=DEFAULT_SCAN_ROOT,
                        help='Known scan directory; used only for rendering.')
    parser.add_argument('--destination', type=Path,
                        help='Required with --render; must be outside the deliverable folder.')
    args = parser.parse_args(argv)
    if args.render and args.destination is None:
        parser.error('--render requires --destination')
    if not args.render and args.destination is not None:
        parser.error('--destination is used only with --render')
    recipes, documents = recipe_snapshot(args.extra_recipes)
    encoded = json.dumps(recipes, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')
    result = {
        'page': PAGE_KEY, 'initial_recipe_count': EMBEDDED_RECIPE_COUNTS[0],
        'embedded_recipe_count': EMBEDDED_RECIPE_COUNT,
        'embedded_recipe_counts_by_source': list(EMBEDDED_RECIPE_COUNTS),
        'recipe_count': len(recipes),
        'extra_recipe_count': len(recipes) - EMBEDDED_RECIPE_COUNT,
        'recipe_counts_by_source': [len(json.loads(d['raw_json'])) for d in documents],
        'recipe_snapshot_sha256': hashlib.sha256(encoded).hexdigest(),
        'source_documents': [{k: d[k] for k in ('path', 'bytes', 'sha256')} for d in documents],
        'transform_order': list(TRANSFORM_ORDER),
        'mode': 'render' if args.render else 'metadata-only',
        'geometry_metadata_valid': True,
        'pixel_extent_bounds_checked': False,
        'images_opened': False,
    }
    if args.render:
        destination = args.destination.expanduser().resolve()
        output_root = OUTPUT_ROOT.resolve()
        if destination == output_root or output_root in destination.parents:
            parser.error('--destination must be outside the deliverable folder')
        # Image libraries are imported only after the explicit render gate.
        from render_crops import render_crop
        result['crops'] = [render_crop(crop, args.scan_root, destination, PAGE_KEY) for crop in recipes]
        result['images_opened'] = True
        result['pixel_extent_bounds_checked'] = True
        result['rendered_count'] = len(result['crops'])
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
